export default function build({ THREE, add, task }) {
  // Initial prototype of the recipe:
  // "Ramp with tall walls from behind start via center height 0.36 to cup rim plus funnel walls behind cup"

  const thickness = 0.012;

  // Helper to create a ramp segment (floor + 2 side walls) from p0 to p1
  function addRampSegment(p0, p1, floorWidth, wallHeight, wallSpacing) {
    const dx = p1[0] - p0[0];
    const dy = p1[1] - p0[1];
    const dz = p1[2] - p0[2];
    const horizLen = Math.hypot(dx, dz);
    const len = Math.hypot(dx, dy, dz);

    // Yaw and pitch so that local X points from p0 to p1, and local Z is horizontal
    const ry = -Math.atan2(dz, dx);
    const rz = Math.atan2(dy, horizLen);

    const cx = (p0[0] + p1[0]) / 2;
    const cy = (p0[1] + p1[1]) / 2;
    const cz = (p0[2] + p1[2]) / 2;

    // Local Y (up perpendicular to ramp): (-sin(rz)*cos(ry), cos(rz), sin(rz)*sin(ry))
    const upX = -Math.sin(rz) * Math.cos(ry);
    const upY = Math.cos(rz);
    const upZ = Math.sin(rz) * Math.sin(ry);

    // Local Z (right perpendicular to ramp, horizontal): (sin(ry), 0, cos(ry))
    const sideX = Math.sin(ry);
    const sideZ = Math.cos(ry);

    // Floor center is shifted down by thickness/2 along local Y so top surface is on p0->p1
    add.box({
      size: [len, thickness, floorWidth],
      position: [
        cx - upX * (thickness / 2),
        cy - upY * (thickness / 2),
        cz - upZ * (thickness / 2),
      ],
      rotation: [0, ry, rz],
      color: '#d4a373',
    });

    // Two tall walls along the sides
    const wallOffsetUp = wallHeight / 2 - thickness;
    for (const s of [-1, 1]) {
      const zOff = s * (wallSpacing / 2 + thickness / 2);
      add.box({
        size: [len, wallHeight, thickness],
        position: [
          cx + upX * wallOffsetUp + sideX * zOff,
          cy + upY * wallOffsetUp,
          cz + upZ * wallOffsetUp + sideZ * zOff,
        ],
        rotation: [0, ry, rz],
        color: '#ccd5ae',
      });
    }
  }

  // Segment 1: behind start to center height 0.36
  addRampSegment([-0.93, 0.68, -0.33], [0.0, 0.36, 0.0], 0.06, 0.07, 0.08);

  // Segment 2: center height 0.36 to cup rim
  addRampSegment([0.0, 0.36, 0.0], [0.74, 0.062, 0.278], 0.06, 0.07, 0.08);

  // Funnel walls behind cup ([0.8, 0, 0.3])
  const cupYaw = -Math.atan2(0.3, 0.8);
  add.box({
    size: [0.16, 0.12, thickness],
    position: [0.85, 0.08, 0.36],
    rotation: [0, cupYaw + 0.5, 0],
    color: '#e9edc9',
  });
  add.box({
    size: [0.16, 0.12, thickness],
    position: [0.88, 0.08, 0.28],
    rotation: [0, cupYaw - 0.5, 0],
    color: '#e9edc9',
  });
}

