import { Worker, isMainThread, parentPort, workerData } from 'node:worker_threads';
import { fileURLToPath } from 'node:url';
import * as THREE from '/workspace/harness/node_modules/three/build/three.module.js';
import * as CANNON from '/workspace/harness/node_modules/cannon-es/dist/cannon-es.js';
import { describeScene, validateDesc, checkSource } from '/workspace/harness/world.mjs';
import { runTrial } from '/workspace/harness/trialrun.mjs';
import { readFileSync } from 'node:fs';
import build from '/workspace/scene.js';

if (!isMainThread) {
  const { desc, seeds } = workerData;
  const failed = [];
  for (const seed of seeds) {
    const { result } = await runTrial({ THREE, CANNON, desc, seed });
    if (!result.success) failed.push(result);
  }
  parentPort.postMessage({ total: seeds.length, failed });
} else {
  checkSource(readFileSync('/workspace/scene.js', 'utf8'));
  const { desc } = describeScene({ THREE, build });
  const usage = validateDesc(desc);
  const total = Number(process.argv[2] || 1000);
  const workers = 10;
  let remaining = workers;
  let allFailed = [];
  const t0 = Date.now();
  for (let w = 0; w < workers; w++) {
    const seeds = [];
    for (let s = w + 1; s <= total; s += workers) seeds.push(s);
    const worker = new Worker(fileURLToPath(import.meta.url), { workerData: { desc, seeds } });
    worker.on('message', (msg) => {
      allFailed.push(...msg.failed);
      if (--remaining === 0) {
